// レッスンデータ。sections は [見出し, HTML] の配列。quiz は [問い, 選択肢, 正解の番号, 解説]。
const table=(heads,rows)=>`<div class="tablewrap"><table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const note=(text)=>`<div class="note">${text}</div>`;
const flow=(items)=>`<div class="flow">${items.map((x,i)=>`${i?'<span class="arrow" aria-hidden="true">→</span>':''}<div class="node">${x}</div>`).join('')}</div>`;
const tree=(root,kids)=>`<div class="tree"><div class="tree-root">${root}</div><div class="tree-kids">${kids.map(k=>`<div class="tree-kid"><b>${k[0]}</b>${k[1]?`<ul>${k[1].map(x=>`<li>${x}</li>`).join('')}</ul>`:''}</div>`).join('')}</div></div>`;

